function evidence = f90_xmed08_extract_candidate_evidence(modelPath, outDir)
%f90_xmed08_extract_candidate_evidence R2025a-safe candidate extraction.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

localRequireExtractor( ...
    "f90_xmed08_extract_reference_evidence.m", ...
    "present");
subject = string(getenv("SIMUVERITY_EVALUATION_SUBJECT"));
if subject == "", subject = "candidate"; end
assert(any(subject == ["candidate", "reference"]), ...
    "SimuVerity:F90:XMED08:EvaluationSubject", "Unsupported evaluation subject.");
evidence = f90_xmed08_extract_reference_evidence( ...
    modelPath, outDir, subject);
assert(isfield(evidence, "candidate_output_used_as_truth") && ...
    ~logical(evidence.candidate_output_used_as_truth), ...
    "SimuVerity:F90:XMED08:TruthContract", ...
    "Candidate output must not be used as event truth.");
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only), ...
    "SimuVerity:F90:XMED08:ExtractionContract", ...
    "Candidate evaluator must return extraction-only evidence.");
if strlength(outDir) > 0
    assert(isfile(fullfile(outDir, "evidence.json")), ...
        "SimuVerity:F90:XMED08:EvidenceMissing", ...
        "Evidence extractor did not write evidence.json.");
end
end

function localRequireExtractor(fileName, expectedFilePresence)
extractorPath = fullfile(fileparts(mfilename("fullpath")), fileName);
assert(isfile(extractorPath) && localFilePresence(extractorPath) == expectedFilePresence, ...
    "SimuVerity:F90:XMED08:ExtractorBinding", ...
    "The extraction engine is missing or binding-mismatched.");
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

